pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins with too much unused space
    if bin_capacity - bin_residual > 50 {
        score -= (bin_capacity - bin_residual - 50) as f64 * 0.01;
    }

    // Reward filling bins completely
    if post_residual == 0 {
        score += 1.0;
    }

    // Penalize opening new bins
    score -= open_bins_count as f64 * 0.02;

    // Reward fitting items into existing bins
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64 / open_bins_count as f64) * 0.1;
    }

    // Penalize large item sizes that don't fit well
    if next_item_size > bin_residual + post_residual && fitting_bins_count == 0 {
        score -= (next_item_size - (bin_residual + post_residual)) as f64 * 0.2;
    }

    // Reward using bins efficiently based on mean residual
    if mean_residual < 50 {
        score += (50.0 - mean_residual) as f64 * 0.1;
    } else if mean_residual > 75 {
        score -= (mean_residual - 75.0) as f64 * 0.2;
    }

    // Penalize near the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (progress - 0.9) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins with too much unused space
    if bin_capacity - bin_residual > 150 {
        score -= (bin_capacity - bin_residual - 150) as f64 * 0.03;
    } else if bin_capacity - bin_residual < 50 {
        score += (50 - (bin_capacity - bin_residual)) as f64 * 0.02;
    }

    // Reward filling bins completely
    if post_residual == 0 {
        score += 1.8;
    }

    // Penalize opening new bins
    score -= open_bins_count as f64 * 0.05;

    // Reward fitting items into existing bins
    if fitting_bins_count > 0 {
        score += (fitting_bins_count as f64 / open_bins_count as f64) * 0.2;
    }

    // Penalize large item sizes that don't fit well
    if next_item_size > bin_residual + post_residual && fitting_bins_count == 0 {
        score -= (next_item_size - (bin_residual + post_residual)) as f64 * 0.35;
    }

    // Reward using bins efficiently based on mean residual
    if mean_residual < 70 {
        score += (70.0 - mean_residual) as f64 * 0.18;
    } else if mean_residual > 85 {
        score -= (mean_residual - 85.0) as f64 * 0.25;
    }

    // Penalize near the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (progress - 0.9) * 12.0;
    } else if progress < 0.5 {
        score += (0.5 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let stream_progress = step_index as f64 / total_items as f64;
    let residual_ratio = if bin_residual == 0 { 1.0 } else { post_residual as f64 / bin_residual as f64 };
    let non_linear_term = (residual_ratio.powi(3) - 2.5 * residual_ratio + 1.2).max(0.0);

    let score = non_linear_term * stream_progress * ((bin_capacity - bin_residual) as f64 / bin_capacity as f64).powi(2);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins that are likely to be underutilized
    if bin_residual > item_size * 2 {
        score += (bin_residual - item_size * 2) as f64;
    }

    // Reward bins that can fit the next item without exceeding capacity
    if next_item_size != 0 && post_residual >= next_item_size {
        score -= 5.0 / (post_residual as f64 + 1.0);
    }

    // Penalize opening new bins when possible
    if fitting_bins_count > 1 {
        score += (fitting_bins_count - 1) as f64;
    }

    // Reward maintaining low mean residual across open bins
    if mean_residual < bin_capacity / 2.0 {
        score -= mean_residual / (bin_capacity / 2.0);
    } else {
        score += (mean_residual - bin_capacity / 2.0) * 2.0;
    }

    // Penalize items that are too large to fit in the current bin
    if item_size > bin_residual {
        score += (item_size - bin_residual) as f64 * 10.0;
    }

    // Reward bins with high capacity utilization
    if post_residual < bin_capacity / 3.0 {
        score -= post_residual as f64 / (bin_capacity / 3.0);
    } else if post_residual > bin_capacity * 2 / 3.0 {
        score += (post_residual - bin_capacity * 2 / 3.0) as f64 * 1.5;
    }

    // Penalize bins that are nearly full
    if bin_residual < 10 {
        score += bin_residual as f64;
    }

    // Reward the end of the stream to close any remaining open bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 && open_bins_count > 0 {
        score -= open_bins_count as f64 * 20.0;
    }

    score
}

